#!/usr/bin/env python3
"""Dump the numbers behind STORY.md from story_extra.json / story_data.json into STORY_numbers.md (regenerated by the
refresh loop, so the write-up's tables stay current as arms land). Windows: lead = days 9-13, then 14-16, 17-23,
24-26, 27-31. "cold" = first question about an object that day, before that day's feedback.

    python3 tools/story_numbers.py  (run from results/regime_search)
"""
import datetime
import json
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = os.path.join(os.path.dirname(ROOT), "confidence_shift_2026-09-20", "uq", "llm_strategies", "STORY_numbers.md")
W = ["lead", "d14_16", "d17_23", "d24_26", "d27_31"]
WL = {"lead": "lead 9-13", "d14_16": "14-16", "d17_23": "17-23", "d24_26": "24-26", "d27_31": "27-31"}
DAYS = {"lead": range(9, 14), "d14_16": range(14, 17), "d17_23": range(17, 24), "d24_26": range(24, 27), "d27_31": range(27, 32)}
MIN_N = 10


def f(v, d=0):
    return "–" if v is None else f"{v:.{d}f}"


def classical_windows(data, pop, key, field=1):
    """pooled accuracy (field 1) or claimed confidence (field 2) per window from story_data.json cells."""
    A = data.get(pop, {}).get("agents", {}).get(key)
    if not A:
        return {w: None for w in W}
    out = {}
    for w in W:
        n = s = 0
        for hh in A:
            for d in DAYS[w]:
                c = A[hh]["all"][d]
                n += c[0]
                s += c[field]
        out[w] = 100 * s / n if n else None
    return out


def main():
    extra = json.load(open(f"{ROOT}/story_extra.json"))
    data = json.load(open(f"{ROOT}/story_data.json"))
    L = [f"# Numbers behind STORY.md — regenerated {datetime.datetime.now().strftime('%a %d %b %Y %H:%M')}", "",
         "Windows: lead = days 9-13 (settled end of the lead-up), 14-16 (first sick days), 17-23 (rest of the spell), 24-26 (first",
         "days back), 27-31 (rest of the return). Accuracy in %, pooled over households. A window with fewer than 10 answers prints –.", ""]
    # classical yardsticks, one-person population
    L += ["## Counters on the one-person-sick population (10 households)", "",
          "| method | " + " | ".join(WL[w] for w in W) + " | claimed conf. lead → 14-16 |", "|---|" + "---|" * (len(W) + 1)]
    for key, name in [("tt3d", "timetable, 3-day memory"), ("ttfrozen", "timetable, never forgets"), ("tt1d", "timetable, 1-day memory"),
                      ("mf3d", "most frequent, 3-day"), ("bma", "hedge over memory lengths"), ("detector3d", "3-day timetable + change alarm"), ("lastseen", "last seen")]:
        acc = classical_windows(data, "person", key, 1)
        conf = classical_windows(data, "person", key, 2)
        L.append(f"| {name} | " + " | ".join(f(acc[w]) for w in W) + f" | {f(conf['lead'])} → {f(conf['d14_16'])} |")
    L.append("")
    # LLM arms, one-person population
    P = extra.get("llm_live", {}).get("person", {})
    L += ["## LLM memories on the one-person-sick population", "",
          "| arm | done | " + " | ".join(WL[w] for w in W) + " | cold 17-23 | cold 24-26 | stated conf. lead → 14-16 | lead-cal. gap 14-16 | ask% / miss% 14-16 |",
          "|---|---|" + "---|" * (len(W) + 5)]
    for key in sorted(P, key=lambda k: (P[k]["mem_kind"], P[k]["msg_tag"])):
        a = P[key]
        Wd = a["windows"]
        acc = {w: (Wd[w]["acc"] if Wd[w] and Wd[w]["n"] >= MIN_N else None) for w in W}
        cold = {w: (Wd[w]["acc_cold"] if Wd[w] and Wd[w].get("n_cold", 0) >= MIN_N else None) for w in W}
        conf = {w: (Wd[w]["conf"] if Wd[w] and Wd[w]["n"] >= MIN_N else None) for w in W}
        gap = (Wd["d14_16"]["leadcal_conf"] - Wd["d14_16"]["acc"]) if Wd["d14_16"] and Wd["d14_16"]["n"] >= MIN_N else None
        g = a.get("askgate") or {}
        ag = g.get("d14_16")
        agtxt = f"{f(ag['ask_rate'])} / {f(ag['miss_rate'])}" if ag and ag["n"] >= MIN_N else "–"
        L.append(f"| {a['name']} | {a['progress'].strip('()')} | " + " | ".join(f(acc[w]) for w in W) +
                 f" | {f(cold['d17_23'])} | {f(cold['d24_26'])} | {f(conf['lead'])} → {f(conf['d14_16'])} | {('+' if gap and gap > 0 else '') + f(gap)} | {agtxt} |")
    L.append("")
    # knowno
    K = extra.get("knowno_live", {}).get("person", {})
    if K:
        L += ["## Three confidence channels + honest sets on the model's own answer (bounded day list, 3 households)", ""]
        for key, a in K.items():
            L += [f"**{a['name']}** — {a['n_hh']} households, {a['n']} questions", "",
                  "| day | n | accuracy | verbalized | agreement | token prob. | MCQ acc. | set coverage | set size /10 |", "|---|---|---|---|---|---|---|---|---|"]
            for d in sorted(a["days"], key=int):
                v = a["days"][d]
                L.append(f"| {d} | {v['n']} | {f(v['acc'])} | {f(v['verbal'])} | {f(v['agree'])} | {f(v['token'])} | {f(v['mcq_acc'])} | {f(v['coverage'])} | {f(v['set_size'], 1)} |")
            L.append("")
    # owner split
    OS = extra.get("owner_split_live", {}).get("partial", {})
    if OS:
        L += ["## Shared-memory interference (one person sick, everyone's things asked; the workshop session's partial-shift arms)", "",
              "| arm | households | whose things | " + " | ".join(WL[w] for w in W) + " |", "|---|---|---|" + "---|" * len(W)]
        for key in ["llm_naive_nomsg", "llm_naive_startmsg", "llm_routine7_nomsg", "llm_routine7_startmsg"]:
            if key not in OS:
                continue
            a = OS[key]
            for grp, label in [("sick_all", "the sick person's"), ("others_all", "everyone else's"), ("others_cold", "everyone else's, cold")]:
                cells = [a["windows"][w][grp] for w in W]
                L.append(f"| {a['name']} | {a['n_hh']} | {label} | " + " | ".join(f(c['acc']) if c and c['n'] >= MIN_N else "–" for c in cells) + " |")
        L.append("")
    # paired contrasts table, regenerated beside the window tables
    P = extra.get("llm_live", {}).get("person", {})
    PL = ["", "## Paired told-vs-untold contrasts (per household, told minus no message)", "",
          "Each cell is the mean across households ± its standard error, then n = households and the sd = how much those",
          "households disagree. Since 22 Sept 07:25 an effect is claimed when |mean| >= 2 standard errors (Oliver's rule);",
          "below 6 households the standard error is estimated from too few numbers to trust, so those rows keep the older",
          "\"bigger than the sd\" floor. ✓ = claimed under whichever bar governs that row. Note the direction of the change:",
          "at 6 households or more, clearing 1 sd implies clearing 2 se, so the new bar only ever adds claims.", "",
          "| arm | window | all questions | cold questions |", "|---|---|---|---|"]
    for key in sorted(P, key=lambda k: (P[k]["mem_kind"], P[k]["msg_tag"])):
        pr = P[key].get("paired_vs_nomsg") or {}
        for w in ("d14_16", "d17_23", "d24_26", "d27_31"):
            p = pr.get(w) or {}
            def cell(v):
                if not v:
                    return "–"
                body = f"{v['mean']:+.1f} ± {v['se']:.1f} (n={v['n_hh']}, sd {v['sd']:.1f})"
                return f"**{body}** ✓" if v["detected"] else body
            if p:
                PL.append(f"| {P[key]['name']} | {WL[w]} | {cell(p.get('all'))} | {cell(p.get('cold'))} |")
    L += PL
    open(OUT, "w").write("\n".join(L) + "\n")
    print(f"wrote {OUT} ({len(L)} lines)")


if __name__ == "__main__":
    main()
